1: // DOCUMENTS: the network — the wiring that lets two-number mini-IP
2: // addressable components exchange messages. Today it carries slim HTTP
3: // requests to a registered server; later stages attach more components
4: // without changing the send/enqueue contract.
5: //
6: // CHECKS: every address crossing the wire is validated as a two-number
7: // mini-IP (<net>.<host>), and sends to unregistered hosts fail loud.
8: const MINI_IP = /^\d+\.\d+$/;
9: 
10: export function createNetwork() {
11:   const servers = new Map();
12: 
13:   function validate(addr) {
14:     if (!MINI_IP.test(addr)) {
15:       throw new Error(`network: invalid mini-IP address ${addr}`);
16:     }
17:   }
18: 
19:   function resolve(address) {
20:     validate(address);
21:     const server = servers.get(address);
22:     if (!server) {
23:       throw new Error(`network: no server at ${address}`);
24:     }
25:     return server;
26:   }
27: 
28:   return {
29:     registerServer(address, server) {
30:       validate(address);
31:       servers.set(address, server);
32:     },
33: 
34:     resolve,
35: 
36:     send({ from, to, request }) {
37:       validate(from);
38:       const server = resolve(to);
39:       const response = server.handleRequest(request);
40:       return { from, to, request, response };
41:     },
42: 
43:     // `isYou` rides through untouched: the engine marks the learner's own
44:     // interactive-browser request, the server stores it on the queue row.
45:     deliverToQueue({ id, from, to, request, atTick, isYou = false }) {
46:       validate(from);
47:       const server = resolve(to);
48:       server.enqueue({ id, from, to, request, atTick, isYou });
49:     },
50:   };
51: }

