29: export function createEngine({
30:   seed = 42,
31:   users = 5,
32:   serviceRate = 4,
33:   arrivalProb = 0.5,
34:   serverAddress = '10.1',
35:   stage = 1,
36:   backendAddresses = ['10.11', '10.12'],
37:   ttlTicks = 10,
38:   cacheAddress = '10.20',
39:   replicationLagTicks = 3,
40:   dbPrimaryAddress = '10.30',
41:   dbReplicaAddress = '10.31',
42:   workerQueueAddress = '10.40',
43:   workerAddress = '10.41',
44:   jobDurationTicks = 2,
45: } = {}) {
46:   if (typeof arrivalProb !== 'number' || arrivalProb < 0 || arrivalProb > 1) {
47:     throw new Error(`engine: arrivalProb must be within [0, 1], got ${arrivalProb}`);
48:   }
49:   if (stage !== 1 && stage !== 2 && stage !== 3 && stage !== 4 && stage !== 5) {
50:     throw new Error(`engine: stage must be 1, 2, 3, 4, or 5, got ${stage}`);
51:   }
52:   const rng = createRng(seed);
53:   const network = createNetwork();
54:   const cache = stage >= 3 ? createCache({ address: cacheAddress, ttlTicks }) : null;
55:   const database =
56:     stage >= 4
57:       ? createDatabase({
58:           primaryAddress: dbPrimaryAddress,
59:           replicaAddress: dbReplicaAddress,
60:           replicationLagTicks,
61:         })
62:       : null;
63:   const workerQueue =
64:     stage === 5
65:       ? createWorkerQueue({
66:           address: workerQueueAddress,
67:           workerAddress,
68:           jobDurationTicks,
69:         })
70:       : null;
71:   let servers;
72:   let lb = null;
73:   if (stage === 1) {
74:     const server = createWebServer({ address: serverAddress, serviceRate });
75:     network.registerServer(serverAddress, server);
76:     servers = [server];
77:   } else {
78:     // Stage 2 wires the LB in front of two duplicated backends; Stage 3
79:     // attaches the shared cache-aside Cache to both backends; Stage 4 adds
80:     // the primary/replica Database; Stage 5 adds the WorkerQueue & Worker.
81:     servers = backendAddresses.map((addr) =>
82:       createWebServer({ address: addr, serviceRate, cache, database, workerQueue }),
83:     );
84:     for (const s of servers) network.registerServer(s.address, s);
85:     lb = createLoadBalancer({ address: serverAddress, backends: backendAddresses, network });
86:     network.registerServer(serverAddress, lb);
87:   }
88:   // The learner's own interactive client shares the crowd's network and
89:   // server pool but keeps its own browser and address; users.js keeps its
90:   // addresses so seeded tick sequences stay identical (PINS above).
91:   const clientBrowser = createBrowser({ name: 'Browser (You)', address: '10.2', network });
92:   const userPool = createUsers({ count: users, serverAddress });
93:   let tick = 0;
94:   let lastExchange = null;
95:   let lastMatchedRoute = null;
96:   let lastFrame = null;
97: 
98:   // The trace machine owns the hop-by-hop trace state; the engine owns the
99:   // clock, the served-exchange record, and browser delivery — the machine
100:   // calls back into these closures as hops execute.
101:   const traceMachine = createTraceMachine({
102:     stage,
103:     serverAddress,
104:     servers,
105:     lb,
106:     network,
107:     cache,
108:     database,
109:     workerQueue,
110:     bumpTick: () => {
111:       tick += 1;
112:       return tick;
113:     },
114:     getTick: () => tick,
115:     onServe: (exchange) => {
116:       lastExchange = exchange;
117:       lastMatchedRoute = exchange.routeId;
118:     },
119:     onFinish: (record) => {
120:       userPool.receiveResponse(record);
121:       if (record.from === '10.2') clientBrowser.receiveResponse(record);
122:     },
123:   });
124: 
125:   return {
126:     step() {
127:       tick += 1;
128:       // TTL eviction happens once per tick, before anything is served:
129:       // expired entries are gone before this tick's work is priced.
130:       if (cache) cache.evictExpired(tick);
131:       // Stage 4+: replication advances one tick at a time.
132:       if (database) database.stepReplication(tick);
133:       // Stage 5: worker queue advances jobs and writes to database.
134:       if (workerQueue) workerQueue.step(database, tick);
135:       const arrivals = userPool.step(rng, arrivalProb);
136:       for (const r of arrivals) {
137:         network.deliverToQueue({
138:           id: `${tick}:${r.userId}`,
139:           from: r.from,
140:           to: r.to,
141:           request: r.request,
142:           atTick: tick,
143:         });
144:       }
145:       const servedBatch = servers.flatMap((s) => s.step(tick));
146:       if (servedBatch.length > 0) {
147:         lastExchange = servedBatch[servedBatch.length - 1];
148:         lastMatchedRoute = lastExchange.routeId;
149:         lastFrame = `${lastExchange.from} -> ${lastExchange.to} | ${lastExchange.request} => ${lastExchange.response}`;
150:         for (const item of servedBatch) {
151:           // Every served exchange is delivered back to its originating
152:           // browser; the learner's own interactive client additionally
153:           // renders anything it originated (trace items or 10.2 crowd rays).
154:           userPool.receiveResponse(item);
155:           if (item.isYou || item.from === '10.2') clientBrowser.receiveResponse(item);
156:         }
157:       }
158:       return this.snapshot();
159:     },
160: 
161:     // One hop per call, delegated to the trace machine: 4 hops in Stage 1
162:     // (emit, route, serve, render); 5 in Stage 2 (LB round-robin between
163:     // route and serve); 6 in Stage 3 (cache check, then response emit);
164:     // 7 in Stage 4 (the database hop inserted after the cache check).
165:     // `from` is the mini-IP of the browser the trace originates from
166:     // (default the learner's own 10.2).
167:     traceHop({ method = 'GET', path = '/about', from = '10.2' } = {}) {
168:       const frame = traceMachine.step({ method, path, from });
169:       if (frame !== null) lastFrame = frame;
170:       return this.snapshot();
171:     },
172: 
173:     setUsers(n) {
174:       userPool.setCount(n);
175:     },
176: 
177:     snapshot() {
178:       const serverSnapshots = servers.map((s) => ({
179:         address: s.address,
180:         ...s.metrics(),
181:         queue: s.queueSnapshot(),
182:         files: s.filesSnapshot(),
183:       }));
184:       const queueDepth = serverSnapshots.reduce((sum, s) => sum + s.queueDepth, 0);
185:       const served = serverSnapshots.reduce((sum, s) => sum + s.served, 0);
186:       const active = serverSnapshots.filter((s) => s.served > 0);
187:       const avgLatencyTicks =
188:         active.length === 0
189:           ? 0
190:           : active.reduce((sum, s) => sum + s.avgLatencyTicks, 0) / active.length;
191:       return {
192:         stage,
193:         tick,
194:         users: userPool.getCount(),
195:         serverAddress,
196:         queueDepth,
197:         served,
198:         avgLatencyTicks,
199:         lastExchange,
200:         queue: serverSnapshots[0].queue,
201:         files: serverSnapshots[0].files,
202:         servers: serverSnapshots,
203:         loadBalancer: lb ? lb.snapshot() : null,
204:         cache: cache ? cache.snapshot(tick) : null,
205:         database: database ? database.snapshot(tick) : null,
206:         workerQueue: workerQueue ? workerQueue.snapshot(tick) : null,
207:         lastMatchedRoute,
208:         lastFrame,
209:         browserDisplay: clientBrowser.last(),
210:         browsers: userPool.getBrowsers(),
211:         trace: traceMachine.snapshot(),
212:       };
213:     },
214:   };
215: }

