1: // DOCUMENTS: the Stage 3 component — a shared cache-aside Cache with
2: // tick-based TTL. It is a real Map lookup on the request path rather than a
3: // probability: entries carry cachedAtTick/expiresAtTick, lookups evict
4: // anything past its TTL first, and hit/miss counters record what actually
5: // happened. Deterministic by construction: no clock, no RNG — time arrives
6: // as the `currentTick` argument, the same way the WebServer keeps time.
7: //
8: // CHECKS: the constructor rejects an address that is not a two-number
9: // mini-IP and a ttlTicks that is not a positive integer (fail-loud over
10: // silent mis-configuration).
11: export function createCache({ address = '10.20', ttlTicks = 10 } = {}) {
12:   if (!/^\d+\.\d+$/.test(address)) {
13:     throw new Error(`cache: invalid mini-IP address ${address}`);
14:   }
15:   if (!Number.isInteger(ttlTicks) || ttlTicks < 1) {
16:     throw new Error(`cache: ttlTicks must be a positive integer, got ${ttlTicks}`);
17:   }
18:   const entries = new Map(); // key -> { key, value, cachedAtTick, expiresAtTick }
19:   let hits = 0;
20:   let misses = 0;
21:   let sets = 0;
22:   let evictions = 0;
23:   let lastLookup = null;
24: 
25:   // An entry is stale the moment the current tick reaches its expiry:
26:   // cached at tick T with ttlTicks = 10 means alive through tick T + 9.
27:   function evictExpired(currentTick = 0) {
28:     for (const entry of entries.values()) {
29:       if (currentTick >= entry.expiresAtTick) {
30:         entries.delete(entry.key);
31:         evictions += 1;
32:       }
33:     }
34:   }
35: 
36:   // Pure membership on the live (post-eviction) entry set — the cheap
37:   // probe step() uses to price a request before serving it.
38:   function has(key, currentTick = 0) {
39:     evictExpired(currentTick);
40:     return entries.has(key);
41:   }
42: 
43:   function get(key, currentTick = 0) {
44:     evictExpired(currentTick);
45:     const entry = entries.get(key);
46:     if (entry) {
47:       hits += 1;
48:       lastLookup = { key, status: 'HIT', atTick: currentTick };
49:       return entry.value;
50:     }
51:     misses += 1;
52:     lastLookup = { key, status: 'MISS', atTick: currentTick };
53:     return null;
54:   }
55: 
56:   function set(key, value, currentTick = 0) {
57:     entries.set(key, {
58:       key,
59:       value,
60:       cachedAtTick: currentTick,
61:       expiresAtTick: currentTick + ttlTicks,
62:     });
63:     sets += 1;
64:   }
65: 
66:   // Stage 4 invalidation: a write through the primary drops the cached copy
67:   // so the next read refills from the database row instead of serving the
68:   // now-outdated value.
69:   function del(key) {
70:     return entries.delete(key);
71:   }
72: 
73:   function snapshot(currentTick = 0) {
74:     evictExpired(currentTick);
75:     return {
76:       address,
77:       ttlTicks,
78:       hits,
79:       misses,
80:       sets,
81:       evictions,
82:       lastLookup,
83:       entries: [...entries.values()].map((e) => ({
84:         key: e.key,
85:         value: e.value,
86:         cachedAtTick: e.cachedAtTick,
87:         expiresAtTick: e.expiresAtTick,
88:         ttlRemaining: e.expiresAtTick - currentTick,
89:       })),
90:     };
91:   }
92: 
93:   return {
94:     get address() {
95:       return address;
96:     },
97:     evictExpired,
98:     has,
99:     get,
100:     set,
101:     del,
102:     snapshot,
103:   };
104: }

