63:     }
64:   }
65: 
66:   function backendFor(targetAddress) {
67:     return servers.find((s) => s.address === targetAddress) ?? servers[0];
68:   }
69: 
70:   function serve(you) {
71:     trace.response = you.response;
72:     trace.status = you.status;
73:     trace.body = you.body;
74:     trace.routeId = you.routeId;
