173:         }
174:       } else if (stage === 3 && trace.hop === 4) {
175:         trace.hop = 5;
176:         if (served) {
177:           serve(served);
178:           frame = `${trace.targetServer} -> ${trace.from} | ${served.response} (${trace.cacheStatus})`;
179:         }
180:       } else if (stage === 3 && trace.hop === 5) {
181:         trace.hop = 6;
182:         finish(trace.targetServer ?? serverAddress);
183:       } else if (stage === 4 && trace.hop === 3) {
184:         // Hop 4/7: the target backend checks Cache and serves the queued
185:         // request (a POST write-through carries cacheStatus INVALIDATE);
186:         // the response record is held so the learner watches the cache
187:         // lookup, then the database hop.
188:         trace.hop = 4;
189:         const backend = backendFor(trace.targetServer);
190:         served = drainUntilYou(backend);
191:         if (served) {
