207:             frame = `Database SELECT ${trace.path} @ ${database.replicaAddress} (${trace.dbStale ? 'STALE' : 'fresh'})`;
208:           } else {
209:             frame = `Database SKIP ${trace.path} (warm cache HIT @ ${cache.address})`;
210:           }
211:         }
212:       } else if (stage === 4 && trace.hop === 5) {
213:         trace.hop = 6;
214:         if (served) {
215:           serve(served);
216:           frame = `${trace.targetServer} -> ${trace.from} | ${served.response} (cache ${trace.cacheStatus})`;
217:         }
