3: // logic splits into focused ES modules/stylesheets; additive test suites
4: // (test/**, e2e/**) fail over 450 lines; static pages (*.html, no partials/
5: // bundler) fail over 550 lines. Non-vacuity: if the selection is empty the
6: // guard itself is broken, so that fails too.
7: import { readFileSync, readdirSync, statSync } from 'node:fs';
8: import { join, relative, sep, extname } from 'node:path';
