28: ]);
29: const SOURCE_DIRS = ['js', 'css', 'e2e', 'test'];
30: const SOURCE_EXT = new Set(['.js', '.css', '.html']);
31: 
32: function walk(dir, out = []) {
33:   for (const name of readdirSync(dir)) {
34:     if (SKIP_DIRS.has(name)) continue;
35:     const full = join(dir, name);
36:     if (statSync(full).isDirectory()) walk(full, out);
37:     else out.push(relative('.', full).split(sep).join('/'));
38:   }
39:   return out;
40: }
41: 
42: const candidates = [
43:   ...SOURCE_DIRS.filter((d) => {
44:     try {
45:       return statSync(d).isDirectory();
46:     } catch {
47:       return false;
48:     }
49:   }).flatMap((d) => walk(d)),
50:   ...walk('.').filter((f) => !f.includes('/') && SOURCE_EXT.has(extname(f))),
51: ];
52: 
53: if (candidates.length === 0) {
54:   console.error('guard-file-size: selection is empty — the guard itself is broken (non-vacuity).');
55:   process.exit(1);
56: }
57: 
58: const offenders = [];
59: for (const file of candidates) {
60:   if (!SOURCE_EXT.has(extname(file))) continue;
61:   const limit = limitFor(file);
62:   const lines = readFileSync(file, 'utf8').split('\n');
