1: // DOCUMENTS: orrery SVG drawing — one concentric ring per architectural
2: // layer (r_k = k * ringGap), one spoke per projected wire, and one satellite
3: // dot per client-ring browser slot. Split from viewport.js by
4: // responsibility (guard-file-size): viewport.js owns the camera and world
5: // positioning; this module turns a layout into the #orrery-svg picture.
6: const SVG_NS = 'http://www.w3.org/2000/svg';
7: 
8: export function svgEl(tag, attrs) {
9:   const el = document.createElementNS(SVG_NS, tag);
10:   for (const [k, v] of Object.entries(attrs)) el.setAttribute(k, String(v));
11:   return el;
12: }
13: 
14: export function drawOrrery(svg, layout) {
15:   const parts = [svgEl('circle', { cx: 0, cy: 0, r: 10, class: 'orrery-core' })];
16:   for (const ring of layout.rings) {
17:     parts.push(svgEl('circle', { cx: 0, cy: 0, r: ring.radius, class: 'orrery-ring' }));
18:   }
19:   for (const wire of layout.wires) {
20:     parts.push(
21:       svgEl('line', {
22:         x1: wire.x1,
23:         y1: wire.y1,
24:         x2: wire.x2,
25:         y2: wire.y2,
26:         class: 'orrery-spoke',
27:       }),
28:     );
29:   }
30:   for (const sat of layout.satellites) {
31:     parts.push(
32:       svgEl('circle', {
33:         cx: sat.x,
34:         cy: sat.y,
35:         r: 6,
36:         class: 'orrery-satellite',
37:         'data-index': sat.index,
38:       }),
39:     );
40:   }
41:   svg.replaceChildren(...parts);
42: }

